// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 amount, uint256 lockTime) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        uint cBalBefore = address(c).balance;
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(cBalAfter == cBalBefore + amount);
    }

    function testFuzz_run(uint256 amount, uint256 lockTime) public {
        _run(amount, lockTime);
    }

    receive() external payable {}
}
